/* PRD 4 layers A and B: the regional hunt chain, the Rare Target and the Hunt's materials.
 *
 * A won random encounter adds one to the chain of the region the player is in (a world map area plus the server bit,
 * ststatus_map_areas's byte); entering another region, the Guardromon teleport and fighting a Rare Target reset it. The
 * card record keeps the chain with its region (definitive_bestiary.c, REC_EXTRA + 8 and + 9), so a save resumes it.
 *
 * Past DEF_HUNT_CHAIN_MIN wins, each random encounter of a region that has a Rare Target (def_hunt_targets, generated by
 * tools/gen_hunt_targets.py) may be swapped for it: an existing boss battle, fought on the encounter's own stage and
 * music, its enemies raised to the region's level, and the party can always flee from it. The Overlevel Rush never
 * offers to skip it: fieldstg_encounter_start asks here before the Rush.
 *
 * The materials (layer B, the owner's model of 2026-11-13). Common: the DEF_HUNT_MATERIALS Hunt Materials, one per band
 * of species (def_hunt_commons, generated: the weakest species give the first); each enemy of a won random encounter, or
 * of one the Rush took, leaves its species' one with a DEF_HUNT_COMMON_PCT chance. Rare: one per region with a Rare
 * Target (index i of def_hunt_targets is region i's), "<lead species> Core <numeral>", the numeral (the table's variant)
 * being the region's rank among those whose target has the same lead species; in battle the Rare Target shows that
 * numeral after its name ("Datamon IV"), so it does not read as the same Digimon at a higher level. Both are counted in
 * the card records at the battle's end (commons in the first, rares in the second: definitive_bestiary.c) and listed on
 * its results screen after the item. A Rare Target also pays DEF_HUNT_XP_MULT times the XP of the encounter it replaced
 * and drops DEF_HUNT_PACKS rare Booster when the battle left no item.
 *
 * Off in a replay script (def_on): no state changes and no pad_random draw, so the scripts' battles are the emulator's. */
#include "common.h"
#include "pad.h"
#include "records.h"
#include "fieldstg.h"

#include "psxstack/savestate.h"

#include "definitive.h"

extern unsigned char ststatus_map_areas[];
extern int def_on(void); /* port.h declares it under PC_PORT only; the host test builds without it */
extern void port_log(const char *fmt, ...);
extern const unsigned char def_str_HuntGotPrefix[], def_str_HuntGotSuffix[], def_str_HuntRarePrefix[], def_str_HuntRareWord[],
    def_str_HuntSpace[], def_str_HuntHeld[], def_str_HuntRomanI[], def_str_HuntRomanV[], def_str_HuntRomanX[];

static struct {
    signed char from_encounter; /* the battle being set up came from a random encounter */
    signed char rare;           /* and it is the Rare Target */
    short level;                /* the Rare Target's level */
    short base;                 /* the encounter's own battle, the one it replaced (layer B's XP) */
    short target;               /* the Rare Target's index in def_hunt_targets: its rare item */
} hunt;

/* A Rare Target won, until its results screen ends (layer B). */
static struct {
    signed char pending; /* a results screen has its XP and Booster to give */
    short base;          /* the battle whose XP it pays DEF_HUNT_XP_MULT times */
    short level;         /* the target's level: the Booster's */
    short pack;          /* the rare Booster the screen gave (def_hunt_take_pack), 0 before */
} reward;

/* The results screen's material lines (layer B): composed at the battle's end, when the species' names are loaded. */
static struct {
    unsigned char text[DEF_HUNT_LINES][DEF_HUNT_LINE_SIZE];
    signed char count, shown;
} lines;

static const DefHuntTarget *target_of(int region) {
    int i;

    for (i = 0; i < def_hunt_target_count; i++) {
        if (def_hunt_targets[i].region == region) {
            return &def_hunt_targets[i];
        }
    }
    return NULL;
}

/* A target's lead species: its battle's first enemy, whose name its rare item and its numeral go with. */
static int lead_of(int t) {
    return fieldstg_battles[def_hunt_targets[t].battle].enemies[0]->digimon;
}

/* ---- Glyph strings: the windows keep the pointer, so every text built here lives in a static buffer. */
static void put(unsigned char *buf, int *p, int size, const unsigned char *s) {
    while (s != NULL && *s != 0 && *p < size - 1) {
        buf[(*p)++] = *s++;
    }
    buf[*p] = 0;
}

static void put_roman(unsigned char *buf, int *p, int size, int n) {
    static const char *const units[10] = { "", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX" };
    const char *u;

    for (; n >= 10; n -= 10) {
        put(buf, p, size, def_str_HuntRomanX);
    }
    for (u = units[n < 0 ? 0 : n]; *u != 0; u++) {
        put(buf, p, size, *u == 'I' ? def_str_HuntRomanI : def_str_HuntRomanV);
    }
}

static void put_count(unsigned char *buf, int *p, int size, int n) {
    if (n >= 10 && *p < size - 2) {
        buf[(*p)++] = (unsigned char)(4 + n / 10 % 10); /* the font's digits: glyph 4 is 0 */
    }
    if (*p < size - 1) {
        buf[(*p)++] = (unsigned char)(4 + n % 10);
    }
    buf[*p] = 0;
}

/* "<lead species> Core <numeral>", rare item `t`'s name. */
static void put_rare_name(unsigned char *buf, int *p, int size, int t) {
    const unsigned char *name = def_species_name(lead_of(t));

    if (name != NULL) {
        put(buf, p, size, name);
        put(buf, p, size, def_str_HuntSpace);
    }
    put(buf, p, size, def_str_HuntRareWord);
    put(buf, p, size, def_str_HuntSpace);
    put_roman(buf, p, size, def_hunt_targets[t].variant);
}

/* A new results line, or NULL when the screen's lines are full. */
static unsigned char *line_new(void) {
    if (lines.count >= DEF_HUNT_LINES) {
        return NULL;
    }
    lines.text[lines.count][0] = 0;
    return lines.text[lines.count++];
}

/* ---- The chain and the Rare Target (layer A). */
int def_hunt_chance(int chain) {
    int c;

    if (chain < DEF_HUNT_CHAIN_MIN) {
        return 0;
    }
    c = DEF_HUNT_CHANCE_BASE + DEF_HUNT_CHANCE_STEP * (chain - DEF_HUNT_CHAIN_MIN);
    return c > DEF_HUNT_CHANCE_MAX ? DEF_HUNT_CHANCE_MAX : c;
}

void def_hunt_map(int map) {
    int region, chain;

    if (!def_on()) {
        return;
    }
    def_record_hunt(&region, &chain);
    if (ststatus_map_areas[map & 0xFF] != region) {
        if (chain != 0) {
            port_log("hunt: region 0x%X -> 0x%X, chain %d reset", region, ststatus_map_areas[map & 0xFF], chain);
        }
        def_record_set_hunt(ststatus_map_areas[map & 0xFF], 0);
    }
}

void def_hunt_chain_reset(void) {
    int region, chain;

    if (!def_on()) {
        return;
    }
    def_record_hunt(&region, &chain);
    def_record_set_hunt(region, 0);
}

int def_hunt_encounter(int battle) {
    const DefHuntTarget *t;
    int region, chain, chance;

    hunt.from_encounter = 0;
    hunt.rare = 0;
    if (!def_on()) {
        return battle;
    }
    hunt.from_encounter = 1;
    def_record_hunt(&region, &chain);
    t = target_of(region);
    chance = def_hunt_chance(chain);
    if (t == NULL || chance == 0) {
        return battle;
    }
    /* The draw only happens once the feature can act, so a region without a target keeps the encounters' sequence. */
    if ((pad_random.next() & 0x7FFF) % 100 >= chance) {
        return battle;
    }
    hunt.rare = 1;
    hunt.level = t->level;
    hunt.base = (short)battle;
    hunt.target = (short)(t - def_hunt_targets);
    port_log("hunt: chain %d in region 0x%X: the Rare Target (battle %d, level %d)", chain, region, t->battle, t->level);
    return t->battle;
}

void def_hunt_scale(void) {
    int i;

    if (!hunt.rare) {
        return;
    }
    for (i = 0; i < 3; i++) {
        RecordsEnemy *e = &records_state.enemies[i];
        long hp;

        if (e->digimon == 0 || e->level <= 0 || e->level >= hunt.level) {
            continue;
        }
        /* The HP grows with the level; the stats already do through the level (stat_scale is left as it is). */
        hp = (long)e->hp * hunt.level / e->level;
        e->hp = (short)(hp > DEF_HUNT_HP_MAX ? DEF_HUNT_HP_MAX : hp);
        e->level = hunt.level;
    }
}

int def_hunt_active(void) {
    return hunt.rare != 0;
}

const unsigned char *def_hunt_foe_name(int species, int slot) {
    static unsigned char buf[2][DEF_HUNT_LINE_SIZE];
    const unsigned char *name;
    int p = 0;

    if (!hunt.rare || hunt.target < 0 || hunt.target >= def_hunt_target_count ||
        (name = def_species_name(species)) == NULL) {
        return NULL;
    }
    slot = slot != 0;
    put(buf[slot], &p, DEF_HUNT_LINE_SIZE, name);
    put(buf[slot], &p, DEF_HUNT_LINE_SIZE, def_str_HuntSpace);
    put_roman(buf[slot], &p, DEF_HUNT_LINE_SIZE, def_hunt_targets[hunt.target].variant);
    return buf[slot];
}

/* ---- The materials (layer B). */

/* A won (or Rush-taken) random encounter: each enemy leaves its species' common material at DEF_HUNT_COMMON_PCT, one
 * line per material ("Hunt material: Bit Shard x2"). A draw per enemy, whatever its species. */
static void common_drops(void) {
    int tally[DEF_HUNT_MATERIALS];
    unsigned char *line;
    int i, m, p;

    for (m = 0; m < DEF_HUNT_MATERIALS; m++) {
        tally[m] = 0;
    }
    for (i = 0; i < 3; i++) {
        int species = records_state.enemies[i].digimon;

        if (species == 0 || (pad_random.next() & 0x7FFF) % 100 >= DEF_HUNT_COMMON_PCT) {
            continue;
        }
        m = def_hunt_common_of(def_bestiary_index(species));
        if (m >= 0) {
            tally[m]++;
        }
    }
    for (m = 0; m < DEF_HUNT_MATERIALS; m++) {
        if (tally[m] == 0) {
            continue;
        }
        def_record_material_add(m, tally[m]);
        port_log("hunt: material %d x%d (now %d)", m, tally[m], def_record_material(m));
        if ((line = line_new()) != NULL) {
            p = 0;
            put(line, &p, DEF_HUNT_LINE_SIZE, def_str_HuntGotPrefix);
            put(line, &p, DEF_HUNT_LINE_SIZE, def_hunt_material_name(m));
            put(line, &p, DEF_HUNT_LINE_SIZE, def_str_HuntSpace);
            put(line, &p, DEF_HUNT_LINE_SIZE, def_str_HuntHeld);
            put_count(line, &p, DEF_HUNT_LINE_SIZE, tally[m]);
            put(line, &p, DEF_HUNT_LINE_SIZE, def_str_HuntGotSuffix);
        }
    }
}

/* A Rare Target won: its region's rare item, counted at once (a save right after keeps it), and its line. */
static void rare_won(int t) {
    unsigned char *line;
    int p = 0;

    if (t < 0 || t >= def_hunt_target_count) {
        return;
    }
    def_record_rare_add(t, 1);
    port_log("hunt: rare %d (now %d)", t, def_record_rare(t));
    if ((line = line_new()) != NULL) {
        put(line, &p, DEF_HUNT_LINE_SIZE, def_str_HuntRarePrefix);
        put_rare_name(line, &p, DEF_HUNT_LINE_SIZE, t);
        put(line, &p, DEF_HUNT_LINE_SIZE, def_str_HuntGotSuffix);
    }
}

void def_hunt_skipped(void) {
    if (hunt.from_encounter && !hunt.rare && def_on()) {
        common_drops(); /* the Rush won it for the party: its enemies still leave their materials (the chain does not count it) */
    }
    hunt.from_encounter = 0;
    hunt.rare = 0;
}

void def_hunt_battle_end(int result) {
    int region, chain;

    if (hunt.from_encounter && def_on()) {
        def_record_hunt(&region, &chain);
        if (hunt.rare) {
            port_log("hunt: Rare Target %s, chain %d reset", result != 0 ? "won" : "left", chain);
            chain = 0;
            if (result != 0) {
                reward.pending = 1;
                reward.base = hunt.base;
                reward.level = hunt.level;
                reward.pack = 0;
                rare_won(hunt.target);
            }
        } else if (result != 0) {
            if (chain < DEF_HUNT_CHAIN_CAP) {
                chain++;
            }
            common_drops();
        }
        def_record_set_hunt(region, chain);
    }
    hunt.from_encounter = 0;
    hunt.rare = 0;
}

const unsigned char *def_hunt_material_name(int material) {
    extern const unsigned char def_str_HuntMat0[], def_str_HuntMat1[], def_str_HuntMat2[], def_str_HuntMat3[],
        def_str_HuntMat4[], def_str_HuntMat5[], def_str_HuntMat6[], def_str_HuntMat7[], def_str_HuntMat8[],
        def_str_HuntMat9[], def_str_HuntMat10[], def_str_HuntMat11[], def_str_HuntMat12[], def_str_HuntMat13[],
        def_str_HuntMat14[], def_str_HuntMat15[];
    static const unsigned char *const names[DEF_HUNT_MATERIALS] = {
        def_str_HuntMat0,  def_str_HuntMat1,  def_str_HuntMat2,  def_str_HuntMat3,  def_str_HuntMat4,  def_str_HuntMat5,
        def_str_HuntMat6,  def_str_HuntMat7,  def_str_HuntMat8,  def_str_HuntMat9,  def_str_HuntMat10, def_str_HuntMat11,
        def_str_HuntMat12, def_str_HuntMat13, def_str_HuntMat14, def_str_HuntMat15,
    };

    return names[material < 0 ? 0 : material >= DEF_HUNT_MATERIALS ? DEF_HUNT_MATERIALS - 1 : material];
}

int def_hunt_common_of(int index) {
    return index >= 0 && index < DEF_BESTIARY_SPECIES && def_hunt_commons[index] < DEF_HUNT_MATERIALS ? def_hunt_commons[index]
                                                                                                       : -1;
}

void def_hunt_species_rares(int species, int *seen, int *total) {
    int i;

    *seen = *total = 0;
    for (i = 0; i < def_hunt_target_count && species != 0; i++) {
        if (lead_of(i) == species) {
            (*total)++;
            *seen += def_record_rare_seen(i) != 0;
        }
    }
}

int def_hunt_reward_battle(void) {
    return reward.pending ? reward.base : -1;
}

int def_hunt_reward_pack(void) {
    int tier;

    if (!reward.pending) {
        return 0;
    }
    tier = reward.level < 25 ? 0 : 1 + (reward.level - 25) / DEF_HUNT_PACK_LEVELS;
    return DEF_HUNT_PACK_FIRST + (tier > 4 ? 4 : tier);
}

int def_hunt_take_pack(void) {
    reward.pack = (short)def_hunt_reward_pack();
    return reward.pack;
}

int def_hunt_pack_count(int item) {
    return reward.pending && reward.pack != 0 && item == reward.pack ? DEF_HUNT_PACKS : 0;
}

int def_hunt_material_pending(void) {
    return lines.shown < lines.count;
}

const unsigned char *def_hunt_material_text(void) {
    static const unsigned char none[1] = { 0 };

    return lines.shown < lines.count ? lines.text[lines.shown++] : none;
}

void def_hunt_reward_done(void) {
    reward.pending = 0;
    reward.pack = 0;
    lines.count = lines.shown = 0;
}

/* Between the swap and the battle's end a save state may be taken (the MCP tests do): it carries whether this is a Rare
 * Target, so a loaded battle still lets the party flee, and the reward and lines a results screen has not shown yet. */
void def_hunt_savestate(struct PortState *s) {
    PORT_STATE_VAR(s, hunt);
    PORT_STATE_VAR(s, reward);
    PORT_STATE_VAR(s, lines);
}
